        public static IPlacedCreatureGetter PlacedCreatureFactory(
            OverlayStream stream,
            BinaryOverlayFactoryPackage package,
            TypedParseParams translationParams = default)
        {
            stream = Decompression.DecompressStream(stream);
            stream = ExtractRecordMemory(
                stream: stream,
                meta: package.MetaData.Constants,
                memoryPair: out var memoryPair,
                offset: out var offset,
                finalPos: out var finalPos);
            var ret = new PlacedCreatureBinaryOverlay(
                memoryPair: memoryPair,
                package: package);
            ret._package.FormVersion = ret;
            ret.CustomFactoryEnd(
                stream: stream,
                finalPos: finalPos,
                offset: offset);
            ret.FillSubrecordTypes(
                majorReference: ret,
                stream: stream,
                finalPos: finalPos,
                offset: offset,
                translationParams: translationParams,
                fill: ret.FillRecordType);
            return ret;
        }

        public static IPlacedCreatureGetter PlacedCreatureFactory(
            ReadOnlyMemorySlice<byte> slice,
            BinaryOverlayFactoryPackage package,
            TypedParseParams translationParams = default)
        {
            return PlacedCreatureFactory(
                stream: new OverlayStream(slice, package),
                package: package,
                translationParams: translationParams);
        }

        public override ParseResult FillRecordType(
            OverlayStream stream,
            int finalPos,
            int offset,
            RecordType type,
            PreviousParse lastParsed,
            Dictionary<RecordType, int>? recordParseCount,
            TypedParseParams translationParams = default)
        {
            type = translationParams.ConvertToStandard(type);
            switch (type.TypeInt)
            {
                case RecordTypeInts.NAME:
                {
                    _BaseLocation = (stream.Position - offset);
                    return (int)PlacedCreature_FieldIndex.Base;
                }
                case RecordTypeInts.XEZN:
                {
                    _EncounterZoneLocation = (stream.Position - offset);
                    return (int)PlacedCreature_FieldIndex.EncounterZone;
                }
                case RecordTypeInts.XRGD:
                {
                    this.RagdollData = BinaryOverlayList.FactoryByStartIndexWithTrigger<IRagdollDataGetter>(
                        stream: stream,
                        package: _package,
                        finalPos: finalPos,
                        itemLength: 28,
                        getter: (s, p) => RagdollDataBinaryOverlay.RagdollDataFactory(s, p));
                    return (int)PlacedCreature_FieldIndex.RagdollData;
                }
                case RecordTypeInts.XRGB:
                {
                    _RagdollBipedRotationLocation = (stream.Position - offset);
                    return (int)PlacedCreature_FieldIndex.RagdollBipedRotation;
                }
                case RecordTypeInts.XPRD:
                case RecordTypeInts.XPPA:
                case RecordTypeInts.INAM:
                case RecordTypeInts.SCHR:
                case RecordTypeInts.TNAM:
                {
                    this.Patrol = PatrolDataBinaryOverlay.PatrolDataFactory(
                        stream: stream,
                        package: _package,
                        translationParams: translationParams.DoNotShortCircuit());
                    return (int)PlacedCreature_FieldIndex.Patrol;
                }
                case RecordTypeInts.XLCM:
                {
                    _LevelModifierLocation = (stream.Position - offset);
                    return (int)PlacedCreature_FieldIndex.LevelModifier;
                }
                case RecordTypeInts.XOWN:
                {
                    _OwnerLocation = (stream.Position - offset);
                    return (int)PlacedCreature_FieldIndex.Owner;
                }
                case RecordTypeInts.XRNK:
                {
                    _FactionRankLocation = (stream.Position - offset);
                    return (int)PlacedCreature_FieldIndex.FactionRank;
                }
                case RecordTypeInts.XMRC:
                {
                    _MerchantContainerLocation = (stream.Position - offset);
                    return (int)PlacedCreature_FieldIndex.MerchantContainer;
                }
                case RecordTypeInts.XCNT:
                {
                    _CountLocation = (stream.Position - offset);
                    return (int)PlacedCreature_FieldIndex.Count;
                }
                case RecordTypeInts.XRDS:
                {
                    _RadiusLocation = (stream.Position - offset);
                    return (int)PlacedCreature_FieldIndex.Radius;
                }
                case RecordTypeInts.XHLP:
                {
                    _HealthLocation = (stream.Position - offset);
                    return (int)PlacedCreature_FieldIndex.Health;
                }
                case RecordTypeInts.XDCR:
                {
                    this.LinkedDecals = BinaryOverlayList.FactoryByArray<ILinkedDecalGetter>(
                        mem: stream.RemainingMemory,
                        package: _package,
                        translationParams: translationParams,
                        getter: (s, p, recConv) => LinkedDecalBinaryOverlay.LinkedDecalFactory(new OverlayStream(s, p), p, recConv),
                        locs: ParseRecordLocations(
                            stream: stream,
                            trigger: LinkedDecal_Registration.TriggerSpecs,
                            triggersAlwaysAreNewRecords: true,
                            constants: _package.MetaData.Constants.SubConstants,
                            skipHeader: false));
                    return (int)PlacedCreature_FieldIndex.LinkedDecals;
                }
                case RecordTypeInts.XLKR:
                {
                    _LinkedReferenceLocation = (stream.Position - offset);
                    return (int)PlacedCreature_FieldIndex.LinkedReference;
                }
                case RecordTypeInts.XCLP:
                {
                    _LinkedReferenceColorLocation = new RangeInt32((stream.Position - offset), finalPos - offset);
                    return (int)PlacedCreature_FieldIndex.LinkedReferenceColor;
                }
                case RecordTypeInts.XAPD:
                {
                    this.ActivateParents = ActivateParentsBinaryOverlay.ActivateParentsFactory(
                        stream: stream,
                        package: _package,
                        translationParams: translationParams.DoNotShortCircuit());
                    return (int)PlacedCreature_FieldIndex.ActivateParents;
                }
                case RecordTypeInts.XESP:
                {
                    _EnableParentLocation = new RangeInt32((stream.Position - offset), finalPos - offset);
                    return (int)PlacedCreature_FieldIndex.EnableParent;
                }
                case RecordTypeInts.XEMI:
                {
                    _EmittanceLightLocation = (stream.Position - offset);
                    return (int)PlacedCreature_FieldIndex.EmittanceLight;
                }
                case RecordTypeInts.XMBR:
                {
                    _MultiboundReferenceLocation = (stream.Position - offset);
                    return (int)PlacedCreature_FieldIndex.MultiboundReference;
                }
                case RecordTypeInts.XATO:
                {
                    _ActivationPromptLocation = (stream.Position - offset);
                    return (int)PlacedCreature_FieldIndex.ActivationPrompt;
                }
                case RecordTypeInts.XIBS:
                {
                    _IsIgnoredBySandboxLocation = (stream.Position - offset);
                    return (int)PlacedCreature_FieldIndex.IsIgnoredBySandbox;
                }
                case RecordTypeInts.XSCL:
                {
                    _ScaleLocation = (stream.Position - offset);
                    return (int)PlacedCreature_FieldIndex.Scale;
                }
                case RecordTypeInts.DATA:
                {
                    _DATALocation = new((stream.Position - offset) + _package.MetaData.Constants.SubConstants.TypeAndLengthLength, finalPos - offset - 1);
                    return (int)PlacedCreature_FieldIndex.Rotation;
                }
                default:
                    return base.FillRecordType(
                        stream: stream,
                        finalPos: finalPos,
                        offset: offset,
                        type: type,
                        lastParsed: lastParsed,
                        recordParseCount: recordParseCount,
                        translationParams: translationParams.WithNoConverter());
            }
